window.addEventListener("DOMContentLoaded",()=>{JSON.parse(localStorage.getItem("appManagerUser"))&&localStorage.removeItem("appManagerUser"),document.getElementById("btn-input").addEventListener("click",e=>{if("password"===e.target.parentNode.parentNode.children[0].type)return e.target.parentNode.parentNode.children[0].type="text",void(e.target.src="/ico/visibility/visibility.svg");e.target.parentNode.parentNode.children[0].type="password",e.target.src="/ico/visibility/visibility_off.svg"},!1),document.getElementById("user").addEventListener("focus",e=>{e.target.parentNode.children[0].classList.remove("intro")}),document.getElementById("user").addEventListener("blur",e=>{""===e.target.value&&e.target.parentNode.children[0].classList.add("intro")}),document.getElementById("password").addEventListener("focus",e=>{e.target.parentNode.parentNode.children[0].classList.remove("intro")}),document.getElementById("password").addEventListener("blur",e=>{""===e.target.value&&e.target.parentNode.parentNode.children[0].classList.add("intro")})}),document.getElementById("form-session").addEventListener("submit",e=>{e.preventDefault(),axios.post(`https://${window.location.host}/user/login`,{user:document.getElementById("user").value.trim(),password:document.getElementById("password").value.trim()}).then(e=>{if(console.log(e),200===e.status)return console.log(e.status),localStorage.setItem("appManagerUser",JSON.stringify({username:`${e.data.name} ${e.data.surName}`,super:e.data.super,admins:e.data.admin,userId:e.data._id})),location.assign("/lobby")}).catch(e=>{console.log(e),400===e.response.status&&(document.getElementById("text-mens").textContent=e.response.data)})});